function draw(ctx,t,p){
  var W=960,H=540;
  function num(v,d){return typeof v==='number'&&isFinite(v)?v:d;}
  function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
  function txt(s,x,y,size,color,align){ctx.fillStyle=color||'#17202a';ctx.font=(size||18)+'px sans-serif';ctx.textAlign=align||'left';ctx.textBaseline='middle';ctx.fillText(s,x,y);}
  function ln(x1,y1,x2,y2,c,w){ctx.strokeStyle=c||'#52636b';ctx.lineWidth=w||2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();}
  function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h);}
  var mode=p&&p.$mode==='explore'?'explore':'presentation';
  var tt=clamp(num(t,0),0,0.999999999);
  var xin=clamp(num(p&&p.x,0),-2,2);
  var vin=clamp(Math.round(num(p&&p.view,0)),0,1);
  var scene=Math.min(2,Math.floor(tt*3));
  var u=tt*3-scene;
  var x=xin, view=vin, focus=0;
  if(mode==='presentation'){
    if(scene===0){x=-2+4*u;view=0;}
    else if(scene===1){
      view=0;
      if(u<0.20)x=-1.7+0.7*(u/0.20);
      else if(u<0.38)x=-1;
      else if(u<0.58)x=-1+2*((u-0.38)/0.20);
      else if(u<0.78)x=1;
      else x=1-0.8*((u-0.78)/0.22);
      focus=u<0.48?-1:1;
    }else{x=-2+4*u;view=u<0.52?0:1;}
  }else{
    x=xin;view=vin;
    focus=Math.abs(x+1)<=Math.abs(x-1)?-1:1;
  }
  x=clamp(x,-2,2);
  var f=function(q){return q*q*q-3*q;};
  var d=function(q){return 3*q*q-3;};
  var fx=f(x),dx=d(x);
  var eps=1e-8;
  var atL=Math.abs(x+1)<eps,atR=Math.abs(x-1)<eps,stationary=atL||atR;
  var interval=x<-1?'[-2,-1)':x<1?'(-1,1)':'(1,2]';
  var sign=dx>eps?1:dx<-eps?-1:0;
  var trend=sign>0?'切线斜率为正；所在区间递增':sign<0?'切线斜率为负；所在区间递减':'切线水平；需比较两侧符号';
  var xmin=-2,xmax=2,ymin=-2.5,ymax=2.5;
  if(scene===1){xmin=focus-0.72;xmax=focus+0.72;ymin=f(focus)-0.72;ymax=f(focus)+0.72;}
  var plot={l:55,r:610,top:105,bot:395};
  function X(q){return plot.l+(q-xmin)/(xmax-xmin)*(plot.r-plot.l);}
  function Y(y){return plot.bot-(y-ymin)/(ymax-ymin)*(plot.bot-plot.top);}
  ctx.clearRect(0,0,W,H);rect(0,0,W,H,'#fbfcf7');rect(35,85,890,335,'#eef4ef');
  txt(scene===0?'S1 当前位置与切线':scene===1?'S2 放大驻点':'S3 符号表总结',650,103,19,'#41615a');
  txt('f(x)=x³−3x',650,135,22,'#17202a');
  txt('f′(x)=3x²−3',650,164,21,'#17202a');
  txt('x='+x.toFixed(2)+'，f(x)='+fx.toFixed(2),650,195,18,'#17202a');
  txt('f′(x)='+dx.toFixed(2),650,222,18,sign>0?'#13795b':sign<0?'#b23a48':'#805500');
  txt(trend,650,249,17,sign>0?'#13795b':sign<0?'#b23a48':'#805500');
  txt('所在符号区间：'+interval,650,276,17,'#17202a');
  if(stationary)txt(atL?'x=-1：左正右负，局部极大':'x=1：左负右正，局部极小',650,303,17,'#805500');
  ctx.save();ctx.beginPath();ctx.rect(plot.l,plot.top,plot.r-plot.l,plot.bot-plot.top);ctx.clip();
  if(scene===1){
    var bandY=plot.bot-42;
    var leftSign=focus===-1?'+':'−',rightSign=focus===-1?'−':'+';
    rect(plot.l,bandY,X(focus)-plot.l,30,focus===-1?'#b9e5cf':'#f4c4c4');
    rect(X(focus),bandY,plot.r-X(focus),30,focus===-1?'#f4c4c4':'#b9e5cf');
    txt(leftSign,X(focus)-Math.min(105,(X(focus)-plot.l)/2),bandY+15,20,focus===-1?'#176b4b':'#9d3040','center');
    txt(rightSign,X(focus)+Math.min(105,(plot.r-X(focus))/2),bandY+15,20,focus===-1?'#9d3040':'#176b4b','center');
    txt('驻点左侧',X(focus)-Math.min(105,(X(focus)-plot.l)/2),bandY-14,15,'#52636b','center');
    txt('驻点右侧',X(focus)+Math.min(105,(plot.r-X(focus))/2),bandY-14,15,'#52636b','center');
  }
  if(view===0){
    var yax=Y(0),xax=X(0);
    if(yax>=plot.top&&yax<=plot.bot)ln(plot.l,yax,plot.r,yax,'#52636b',1.5);
    if(xax>=plot.l&&xax<=plot.r)ln(xax,plot.top,xax,plot.bot,'#52636b',1.5);
    var step=scene===1?0.25:1;
    for(var q=Math.ceil(xmin/step)*step;q<=xmax+1e-8;q+=step){if(q>=-2&&q<=2){var xp=X(q);ln(xp,yax-4,xp,yax+4,'#52636b',1);if(Math.abs(q-Math.round(q))<1e-7)txt(String(Math.round(q)),xp,yax+20,15,'#52636b','center');}}
    ctx.strokeStyle='#176b87';ctx.lineWidth=3;ctx.beginPath();
    for(var i=0;i<=300;i++){var q2=xmin+(xmax-xmin)*i/300;var yy=Y(f(q2));if(i===0)ctx.moveTo(X(q2),yy);else ctx.lineTo(X(q2),yy);}ctx.stroke();
    ctx.strokeStyle='#d26a3a';ctx.lineWidth=2;ctx.beginPath();
    var ql=xmin,qr=xmax;ctx.moveTo(X(ql),Y(fx+dx*(ql-x)));ctx.lineTo(X(qr),Y(fx+dx*(qr-x)));ctx.stroke();
    var px=X(x),py=Y(fx);ctx.fillStyle='#d22f45';ctx.beginPath();ctx.arc(px,py,6,0,Math.PI*2);ctx.fill();
    txt('P('+x.toFixed(2)+','+fx.toFixed(2)+')',px+10,py-16,16,'#b12a3d');
    if(stationary)txt('水平切线',px+12,py+20,16,'#805500');
    if(scene===1){txt('放大视窗：x∈['+xmin.toFixed(2)+','+xmax.toFixed(2)+']',plot.l+8,plot.top+17,15,'#52636b');}
  }else{
    var by=220;rect(plot.l,by,X(-1)-plot.l,48,'#b9e5cf');rect(X(-1),by,X(1)-X(-1),48,'#f4c4c4');rect(X(1),by,plot.r-X(1),48,'#b9e5cf');
    txt('＋ 递增',X(-1)-105,by+24,18,'#176b4b','center');txt('− 递减',X(0),by+24,18,'#9d3040','center');txt('＋ 递增',X(1)+105,by+24,18,'#176b4b','center');
    txt('[-2,-1)',X(-1)-105,by-18,16,'#52636b','center');txt('(-1,1)',X(0),by-18,16,'#52636b','center');txt('(1,2]',X(1)+105,by-18,16,'#52636b','center');
    ln(X(-2),by+72,X(2),by+72,'#52636b',2);ln(X(-1),by+64,X(-1),by+80,'#52636b',2);ln(X(1),by+64,X(1),by+80,'#52636b',2);ln(X(x),by-8,X(x),by+58,'#805500',2);txt('当前位置',X(x),by-25,15,'#805500','center');
  }
  ctx.restore();
  if(view===0&&scene!==1){var px2=X(x),py2=Y(fx);ln(px2,py2,px2,Y(0),'#a24d38',1.5);}
  txt(view===0?'图像视图':'导数符号带视图',650,335,18,'#41615a');
  txt('正号：对应区间递增；负号：对应区间递减',650,363,16,'#52636b');
  txt('导数为零只给出驻点条件，极值还需看两侧变号',650,389,16,'#52636b');
  var title,caption;
  if(mode==='presentation'){
    if(scene===0){title='切线斜率与函数走势';caption=sign>0?'切线斜率为正，当前位置属于递增区间。':sign<0?'切线斜率为负，当前位置属于递减区间。':'切线水平；驻点要结合两侧符号判断。';}
    else if(scene===1){title='驻点与局部极值';caption=atL?'x=-1 处切线水平；左侧导数为正、右侧为负，所以是局部极大。':atR?'x=1 处切线水平；左侧导数为负、右侧为正，所以是局部极小。':'放大驻点附近，比较左右颜色所示的导数符号。';}
    else{title='用符号表概括增减';caption='在 [-2,2] 内，函数先增、后减、再增；两个驻点的两侧符号变号，分别给出极大与极小。';}
  }else{
    title=view===0?'导数符号与函数走势：图像探索':'导数符号带：查看增减区间';
    caption=atL?'当前恰为 x=-1：左正右负，因此是局部极大。':atR?'当前恰为 x=1：左负右正，因此是局部极小。':sign>0?'当前切线斜率为正，且所在区间 [-2,-1) 或 (1,2] 递增。':sign<0?'当前切线斜率为负，且所在区间 (-1,1) 递减。':'当前是驻点；仅凭导数为零不能单独断定极值。';
  }
  return {metrics:{x:x,f:fx,derivative:dx,view:view,stationary:stationary,atLeft:atL,atRight:atR,scene:scene,viewport:{xmin:xmin,xmax:xmax,ymin:ymin,ymax:ymax},focus:focus},controls:{x:x,view:view},disabled:{},title:title,caption:caption};
}
